{{!-- Styling parameters: class, avatarClass, contentClass, titleClass, descriptionClass, metaClass --}}
{{#with this as |ghostcnStyles|}}
{{!--
  Component: Author Card
  Usage: In post context {{> "components/author-card"}} or {{#primary_author}}{{> "components/author-card"}}{{/primary_author}}
--}}
<section class="gh-author-card{{#if ghostcnStyles.class}} {{ghostcnStyles.class}}{{/if}}">
    {{#if profile_image}}
    <img src="{{img_url profile_image size="m"}}" alt="{{name}}" class="gh-author-avatar{{#if ghostcnStyles.avatarClass}} {{ghostcnStyles.avatarClass}}{{/if}}" />
    {{else}}
    <div class="gh-author-avatar-fallback{{#if ghostcnStyles.avatarClass}} {{ghostcnStyles.avatarClass}}{{/if}}" aria-hidden="true">
        {{name.[0]}}
    </div>
    {{/if}}

    <div class="gh-author-details{{#if ghostcnStyles.contentClass}} {{ghostcnStyles.contentClass}}{{/if}}">
        <div class="gh-author-heading">
            <h4 class="gh-author-name{{#if ghostcnStyles.titleClass}} {{ghostcnStyles.titleClass}}{{/if}}">
                <a href="{{url}}" >{{name}}</a>
            </h4>
            {{#if count.posts}}
            <span class="gh-author-post-count">
                {{plural count.posts empty="0 posts" singular="% post" plural="% posts"}}
            </span>
            {{/if}}
        </div>

        {{#if bio}}
        <p class="gh-author-bio{{#if ghostcnStyles.descriptionClass}} {{ghostcnStyles.descriptionClass}}{{/if}}">{{bio}}</p>
        {{/if}}

        <div class="gh-author-meta{{#if ghostcnStyles.metaClass}} {{ghostcnStyles.metaClass}}{{/if}}">
            {{#if location}}
            <span class="gh-author-location"><svg aria-hidden="true" viewBox="0 0 16 16" width="13" height="13" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M8 14s5-4.4 5-8a5 5 0 1 0-10 0c0 3.6 5 8 5 8Z"/><circle cx="8" cy="6" r="1.75"/></svg>{{location}}</span>
            {{/if}}
            {{#if website}}
            <a href="{{website}}" target="_blank" rel="noopener noreferrer" class="gh-author-link">Website</a>
            {{/if}}
            {{#if twitter}}
            <a href="{{social_url type="twitter"}}" target="_blank" rel="noopener noreferrer" class="gh-author-link">Twitter/X</a>
            {{/if}}
            {{#if facebook}}
            <a href="{{social_url type="facebook"}}" target="_blank" rel="noopener noreferrer" class="gh-author-link">Facebook</a>
            {{/if}}
        </div>
    </div>
</section>
{{/with}}

/* ghostcn: Author Card Styles */
.gh-author-card {
    box-sizing: border-box; min-width: 0; overflow-wrap: anywhere; border: 1px solid var(--border, #e4e4e7); border-radius: var(--ghcn-panel-radius, min(var(--radius, 8px), 24px)); background: var(--card, #fff); color: var(--card-foreground, #09090b);
    font-family: inherit;
    font-size: var(--ghcn-text-body, 16px);
    line-height: 1.5;
    isolation: isolate;
    padding: var(--ghcn-panel-padding, clamp(16px, 3vw, 24px));
    margin: var(--ghcn-section-space, clamp(24px, 4vw, 48px)) auto;
    width: min(100% - 32px, 704px);
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: var(--ghcn-grid-gap, 16px);
}

.gh-author-card *,
.gh-author-card *::before,
.gh-author-card *::after {
    box-sizing: border-box;
}

@media (min-width: 640px) {
    .gh-author-card {
        flex-direction: row;
        align-items: flex-start;
    }
}

.gh-author-avatar {
    width: 56px;
    height: 56px;
    flex: 0 0 56px;
    border-radius: 9999px;
    object-fit: cover;
    border: 2px solid var(--border, #e4e4e7);
    box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
}

.gh-author-avatar-fallback {
    width: 56px;
    height: 56px;
    flex: 0 0 56px;
    border-radius: 9999px;
    background-color: var(--muted, #f4f4f5);
    color: var(--foreground, #09090b);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 24px;
    font-weight: 700;
    border: 2px solid var(--border, #e4e4e7);
    box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
}

.gh-author-details {
    flex: 1;
    min-width: 0;
    text-align: center;
}

@media (min-width: 640px) {
    .gh-author-details {
        text-align: left;
    }
}

.gh-author-name {
    font-size: var(--ghcn-title-card, 20px); font-weight: 650; line-height: 1.3; letter-spacing: -.025em; color: inherit;
    margin: 0;
}

.gh-author-name a {
    color: inherit;
    text-decoration: none;
    transition: color 0.15s ease;
}

.gh-author-name:hover {
    color: var(--primary, var(--ghost-accent-color, #18181b));
}

.gh-author-bio {
    color: var(--muted-foreground, #71717a);
    font-size: 14px;
    line-height: 1.5;
    margin: 8px 0 16px;
}

.gh-author-meta {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: center;
    gap: 16px;
    font-size: 12px;
    color: var(--muted-foreground, #71717a);
}

.gh-author-meta a {
    color: var(--primary, var(--ghost-accent-color, #18181b));
    text-decoration: none;
}

.gh-author-meta a:hover {
    text-decoration: underline;
}

.gh-author-heading { display: flex; flex-direction: column; justify-content: space-between; gap: 8px; margin-bottom: 8px; }
.gh-author-post-count { border-radius: 9999px; padding: 4px 10px; background: var(--muted); color: var(--muted-foreground); font-size: 12px; font-weight: 500; }
.gh-author-location { display: inline-flex; align-items: center; gap: 4px; }
@media (min-width: 640px) { .gh-author-heading { flex-direction: row; flex-wrap: wrap; align-items: center; } .gh-author-meta { justify-content: flex-start; } }
.gh-author-card:focus-visible, :where(.gh-author-card) :focus-visible { outline: 2px solid var(--ring, currentColor); outline-offset: 2px; }
